selector_to_html = {"a[href=\"#linux-arm64\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Linux ARM64<a class=\"headerlink\" href=\"#linux-arm64\" title=\"Link to this heading\">#</a></h3><p>The dependency commands below apply to Debian/Ubuntu. Building vLLM 0.24.0 for ARM CPU requires NEON, and GCC/G++ 12.3 or later is recommended.</p>", "a[href=\"#create-the-python-environment\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. Create the Python environment<a class=\"headerlink\" href=\"#create-the-python-environment\" title=\"Link to this heading\">#</a></h3><p>The expected Python version is 3.11 and the architecture is <code class=\"docutils literal notranslate\"><span class=\"pre\">arm64</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">aarch64</span></code>.</p>", "a[href=\"#build-vllm-0-24-0-for-cpu\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5. Build vLLM 0.24.0 for CPU<a class=\"headerlink\" href=\"#build-vllm-0-24-0-for-cpu\" title=\"Link to this heading\">#</a></h3><p>Verify the version and the build type:</p>", "a[href=\"#install-flaggems-and-vllm-plugin-fl\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">6. Install FlagGems and vllm-plugin-FL<a class=\"headerlink\" href=\"#install-flaggems-and-vllm-plugin-fl\" title=\"Link to this heading\">#</a></h3><p>The ARM CPU integration is a Python path and does not require <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_VENDOR=arm</span></code>. If the current shell inherited configuration for another hardware backend, clear it first.</p>", "a[href=\"#out-of-memory\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Out of memory<a class=\"headerlink\" href=\"#out-of-memory\" title=\"Link to this heading\">#</a></h3><p>This document uses <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_CPU_KVCACHE_SPACE=1</span></code> to allocate a fixed 1 GiB KV cache for the 512-token, batch-size-1 smoke test. If the context length or the concurrency is changed, adjust it again based on the startup log; if the model weights themselves cannot be loaded completely, increasing the KV cache will not help.</p>", "a[href=\"#the-platform-is-not-cpuplatform\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">The platform is not CpuPlatform<a class=\"headerlink\" href=\"#the-platform-is-not-cpuplatform\" title=\"Link to this heading\">#</a></h3><p>On Linux, confirm that the installed vLLM is a CPU build; on an ARM+GPU/NPU host, also confirm that no other device plugin was selected. Do not fake <code class=\"docutils literal notranslate\"><span class=\"pre\">platform.machine()</span></code> or force a monkey-patch of <code class=\"docutils literal notranslate\"><span class=\"pre\">current_platform</span></code> to bypass the check.</p>", "a[href=\"#model-preparation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Model preparation<a class=\"headerlink\" href=\"#model-preparation\" title=\"Link to this heading\">#</a></h2><p>This document uses MiniCPM-2B from ModelScope. The download command uses the ModelScope 1.39.1 CLI:</p>", "a[href=\"#environment-setup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment setup<a class=\"headerlink\" href=\"#environment-setup\" title=\"Link to this heading\">#</a></h2><h3>Pre-run checks<a class=\"headerlink\" href=\"#pre-run-checks\" title=\"Link to this heading\">#</a></h3><p>First confirm that the host architecture is <code class=\"docutils literal notranslate\"><span class=\"pre\">arm64</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">aarch64</span></code>:</p>", "a[href=\"#flaggems-import-fails\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">FlagGems import fails<a class=\"headerlink\" href=\"#flaggems-import-fails\" title=\"Link to this heading\">#</a></h3><p>The plugin\u2019s shared utility module imports FlagGems. Without FlagGems the <code class=\"docutils literal notranslate\"><span class=\"pre\">fl</span></code> entry point cannot load completely, and the W4A8 checkpoint used in this document cannot run either. Check the actual path:</p>", "a[href=\"#stop-the-service\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5. Stop the service<a class=\"headerlink\" href=\"#stop-the-service\" title=\"Link to this heading\">#</a></h3><p>Go back to terminal A, press <code class=\"docutils literal notranslate\"><span class=\"pre\">Ctrl-C</span></code>, and wait for the API server, EngineCore and worker to exit.</p>", "a[href=\"#arm-cpu-empty-vllm-0-24-0-vllm-plugin-fl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">ARM CPU + empty vLLM 0.24.0 + vllm-plugin-FL<a class=\"headerlink\" href=\"#arm-cpu-empty-vllm-0-24-0-vllm-plugin-fl\" title=\"Link to this heading\">#</a></h1><p>This document explains how to install vLLM 0.24.0, vllm-plugin-FL, FlagGems and flagtree-cpu from source on an ARM64 CPU, and how to complete a lightweight text inference validation with MiniCPM-2B.</p><p>vllm-plugin-FL handles vLLM plugin registration, ARM CPU platform selection, packed checkpoint integration and the CPU compatibility handling for Qwen GDN; FlagGems provides W4A8-G128 weight packing and the Triton kernel; flagtree-cpu compiles Triton programs to the ARM CPU.</p>", "a[href=\"#run-the-vllm-plugin-fl-arm-interface-tests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. Run the vllm-plugin-FL ARM interface tests<a class=\"headerlink\" href=\"#run-the-vllm-plugin-fl-arm-interface-tests\" title=\"Link to this heading\">#</a></h3><p>For the commit used in this document the result on a Mac M5 Pro is <code class=\"docutils literal notranslate\"><span class=\"pre\">16</span> <span class=\"pre\">passed</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">0</span> <span class=\"pre\">skipped</span></code>. This covers ARM CPU platform registration, GPU backend isolation on an ARM host, GDN patch idempotency and the packed W4A8 parameter contract.</p>", "a[href=\"#send-a-text-request\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4. Send a text request<a class=\"headerlink\" href=\"#send-a-text-request\" title=\"Link to this heading\">#</a></h3><p>In terminal B, first check the health status and the model name:</p>", "a[href=\"#run-the-flaggems-w4a8-numerical-tests\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. Run the FlagGems W4A8 numerical tests<a class=\"headerlink\" href=\"#run-the-flaggems-w4a8-numerical-tests\" title=\"Link to this heading\">#</a></h3><p>For the commit used in this document the result on a Mac M5 Pro is <code class=\"docutils literal notranslate\"><span class=\"pre\">7</span> <span class=\"pre\">passed</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">0</span> <span class=\"pre\">skipped</span></code>. The tests execute the Triton W4A8-G128 kernel and compare it against the PyTorch reference implementation; if all tests are skipped, that does not count as passing.</p>", "a[href=\"#download-and-pin-the-source-versions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. Download and pin the source versions<a class=\"headerlink\" href=\"#download-and-pin-the-source-versions\" title=\"Link to this heading\">#</a></h3><p>Confirm each checkout:</p>", "a[href=\"#verify-the-plugin-and-the-cpu-platform\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">7. Verify the plugin and the CPU platform<a class=\"headerlink\" href=\"#verify-the-plugin-and-the-cpu-platform\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_PLUGINS</span></code> is the plugin filter variable provided by vLLM. <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_PLUGINS=fl</span></code> loads only the installed plugin named <code class=\"docutils literal notranslate\"><span class=\"pre\">fl</span></code>; it does not detect ARM and cannot replace <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGGEMS_VENDOR=arm</span></code>.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGGEMS_VENDOR=arm</span></code> must be set before the current process first imports <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">vllm_fl</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">vllm</span></code>:</p>", "a[href=\"run-inference-task.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Run an inference task<a class=\"headerlink\" href=\"#run-an-inference-task\" title=\"Link to this heading\">#</a></h1><p>With vLLM and vllm-plugin-FL <a class=\"reference internal\" href=\"install.html\"><span class=\"std std-doc\">installed</span></a>, you can run inference in two ways: offline batched inference (load the model directly in a Python script) or serving inference (start an API server and send requests). Choose the approach that fits your use case.</p>", "a[href=\"#pre-run-checks\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Pre-run checks<a class=\"headerlink\" href=\"#pre-run-checks\" title=\"Link to this heading\">#</a></h3><p>First confirm that the host architecture is <code class=\"docutils literal notranslate\"><span class=\"pre\">arm64</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">aarch64</span></code>:</p>", "a[href=\"#software-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Software environment<a class=\"headerlink\" href=\"#software-environment\" title=\"Link to this heading\">#</a></h2><p>Related review links:</p>", "a[href=\"#start-the-text-service\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. Start the text service<a class=\"headerlink\" href=\"#start-the-text-service\" title=\"Link to this heading\">#</a></h3><p>In terminal A:</p>", "a[href=\"#hardware-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware environment<a class=\"headerlink\" href=\"#hardware-environment\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#the-first-request-does-not-return-for-a-long-time\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">The first request does not return for a long time<a class=\"headerlink\" href=\"#the-first-request-does-not-return-for-a-long-time\" title=\"Link to this heading\">#</a></h3><p>First check whether the worker is still running and consuming CPU; the first Triton/LLVM JIT can take several minutes. If the server has already printed an exception, take the exception as authoritative: an ABI mismatch, a missing shared library, an undefined symbol or an architecture error must not be interpreted as \u201cstill compiling\u201d.</p>", "a[href=\"#build-flagtree-cpu-triton-3-7-2\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4. Build flagtree-cpu / Triton 3.7.2<a class=\"headerlink\" href=\"#build-flagtree-cpu-triton-3-7-2\" title=\"Link to this heading\">#</a></h3><p>Verify that the current Python loads the flagtree-cpu just installed:</p>", "a[href=\"#installation-procedure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Installation procedure<a class=\"headerlink\" href=\"#installation-procedure\" title=\"Link to this heading\">#</a></h2><p>The commands below use a fresh working directory, so that an existing vLLM, Triton, FlagGems or plugin installation is not loaded.</p>", "a[href=\"#faq\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">FAQ<a class=\"headerlink\" href=\"#faq\" title=\"Link to this heading\">#</a></h2><h3>The plugin is not loaded<a class=\"headerlink\" href=\"#the-plugin-is-not-loaded\" title=\"Link to this heading\">#</a></h3><p>Check the entry points:</p>", "a[href=\"#macos\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">macOS<a class=\"headerlink\" href=\"#macos\" title=\"Link to this heading\">#</a></h3><p>macOS requires Apple Silicon, Xcode Command Line Tools, Homebrew and Python 3.11:</p>", "a[href=\"#the-plugin-is-not-loaded\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">The plugin is not loaded<a class=\"headerlink\" href=\"#the-plugin-is-not-loaded\" title=\"Link to this heading\">#</a></h3><p>Check the entry points:</p>", "a[href=\"#install-the-python-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. Install the Python dependencies<a class=\"headerlink\" href=\"#install-the-python-dependencies\" title=\"Link to this heading\">#</a></h3><p>Create the constraints file:</p>", "a[href=\"#eager-mode-validated\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">eager mode (validated)<a class=\"headerlink\" href=\"#eager-mode-validated\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">vllm</span> <span class=\"pre\">serve</span></code> command in the \u201cTest procedure\u201d section above is the validated command. The Mac re-validation on 2026-09-04 used vLLM source commit <code class=\"docutils literal notranslate\"><span class=\"pre\">ee0da84a</span></code>, FlagGems <code class=\"docutils literal notranslate\"><span class=\"pre\">1fda4b11</span></code>, vllm-plugin-FL <code class=\"docutils literal notranslate\"><span class=\"pre\">58a690b</span></code>, Qwen3-1.7B BF16, batch size 1 and <code class=\"docutils literal notranslate\"><span class=\"pre\">--enforce-eager</span></code>. The service loads 2 safetensors shards and the log confirms that the CPU KV cache is pinned to 1 GiB; <code class=\"docutils literal notranslate\"><span class=\"pre\">/health</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/models</span></code> and streaming <code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/chat/completions</span></code> requests all return HTTP 200, and the client receives 16 non-empty text tokens.</p>", "a[href=\"#openmp-is-not-found-on-macos\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">OpenMP is not found on macOS<a class=\"headerlink\" href=\"#openmp-is-not-found-on-macos\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#test-procedure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Test procedure<a class=\"headerlink\" href=\"#test-procedure\" title=\"Link to this heading\">#</a></h2><p>Run the tests in the following order. The first two steps confirm the kernel and the plugin interface and cannot be replaced by a single model generation.</p>", "a[href=\"#test-command\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Test command<a class=\"headerlink\" href=\"#test-command\" title=\"Link to this heading\">#</a></h2><h3>eager mode (validated)<a class=\"headerlink\" href=\"#eager-mode-validated\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">vllm</span> <span class=\"pre\">serve</span></code> command in the \u201cTest procedure\u201d section above is the validated command. The Mac re-validation on 2026-09-04 used vLLM source commit <code class=\"docutils literal notranslate\"><span class=\"pre\">ee0da84a</span></code>, FlagGems <code class=\"docutils literal notranslate\"><span class=\"pre\">1fda4b11</span></code>, vllm-plugin-FL <code class=\"docutils literal notranslate\"><span class=\"pre\">58a690b</span></code>, Qwen3-1.7B BF16, batch size 1 and <code class=\"docutils literal notranslate\"><span class=\"pre\">--enforce-eager</span></code>. The service loads 2 safetensors shards and the log confirms that the CPU KV cache is pinned to 1 GiB; <code class=\"docutils literal notranslate\"><span class=\"pre\">/health</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/models</span></code> and streaming <code class=\"docutils literal notranslate\"><span class=\"pre\">/v1/chat/completions</span></code> requests all return HTTP 200, and the client receives 16 non-empty text tokens.</p>", "a[href=\"#behavior-when-a-gpu-or-npu-is-also-installed-on-the-arm-host\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Behavior when a GPU or NPU is also installed on the ARM host<a class=\"headerlink\" href=\"#behavior-when-a-gpu-or-npu-is-also-installed-on-the-arm-host\" title=\"Link to this heading\">#</a></h2><p>An ARM64 CPU architecture does not mean that vLLM necessarily selects the CPU backend. The plugin registers the vLLM CPU platform and installs the GDN compatibility handling only when both of the following conditions hold:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
